<section class="page-hero page-hero-compact"><div class="container"><span class="eyebrow">YOUR PROGRESS</span><h1>My applications</h1><p>Review your application history and the latest status of each submission.</p></div></section>
<section class="section"><div class="container"><div class="panel">
    <?php if ($applications === []): ?><div class="empty-state"><span class="empty-icon">↗</span><h2>Your application list is clear.</h2><p>When you apply to an opportunity, you can track its progress here.</p><a class="button button-primary" href="<?= e(pageUrl('opportunities')) ?>">Explore opportunities</a></div>
    <?php else: ?><div class="table-wrap"><table><thead><tr><th>Opportunity</th><th>Organization</th><th>Submitted</th><th>Status</th><th>Status history</th><th>Action</th></tr></thead><tbody><?php foreach ($applications as $application): ?><tr><td><a href="<?= e(pageUrl('opportunity', ['id' => (int) $application['opportunity_id']])) ?>"><?= e($application['title']) ?></a></td><td><?= e($application['organization_name'] ?? 'Institution opportunity') ?></td><td><?= e(date('M j, Y', strtotime($application['submitted_at']))) ?></td><td><span class="status status-<?= e($application['status']) ?>"><?= e(str_replace('_', ' ', ucfirst($application['status']))) ?></span></td><td><details><summary>View updates (<?= e(count($application['status_history'])) ?>)</summary><ul class="status-history"><?php foreach ($application['status_history'] as $event): ?><li><strong><?= e(str_replace('_', ' ', ucfirst($event['status']))) ?></strong><span><?= e(date('M j, Y g:i a', strtotime($event['created_at']))) ?><?= $event['changed_by'] ? ' · ' . e($event['changed_by']) : '' ?></span></li><?php endforeach; ?></ul></details></td><td><?php if (in_array($application['status'], ['submitted','under_review','shortlisted','interview'], true)): ?><form method="post" action="<?= e(pageUrl('applications')) ?>" data-confirm="Withdraw this application?"><?= formToken() ?><input type="hidden" name="action" value="withdraw_application"><input type="hidden" name="application_id" value="<?= e($application['id']) ?>"><button class="button button-text button-danger" type="submit">Withdraw</button></form><?php else: ?><span class="muted">—</span><?php endif; ?></td></tr><?php endforeach; ?></tbody></table></div><?php endif; ?>
</div></div></section>
